<?php
/** Monthly planning revisions; no financial posting and no legacy promotion. */
require_once __DIR__.'/report_configuration.php';require_once __DIR__.'/notifications.php';
class BudgetCellProblem extends ReportingProblem
{
    public array $cell;
    public function __construct(string $message,int $account,?int $project,int $status=400){parent::__construct($message,$status);$this->cell=['account_id'=>$account,'project_id'=>$project];}
}
function budget_trigger_contract(): array
{
    return [
        'r6_budget_revision_update'=>['budget_revisions','UPDATE',"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Submitted budget content is immutable'; END"],
        'r6_budget_revision_delete'=>['budget_revisions','DELETE',"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Submitted budget content is immutable'; END"],
        'r6_budget_allocation_update'=>['budget_revision_allocations','UPDATE',"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Submitted budget allocations are immutable'; END"],
        'r6_budget_allocation_delete'=>['budget_revision_allocations','DELETE',"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Submitted budget allocations are immutable'; END"],
        'r6_budget_allocation_insert'=>['budget_revision_allocations','INSERT',"BEGIN IF NOT EXISTS(SELECT 1 FROM budget_revisions r JOIN budget_revision_drafts d ON d.id=r.draft_id WHERE r.id=NEW.revision_id AND d.state='Draft' AND d.submitted_revision_id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Submitted budget allocations cannot be extended'; END IF; END"],
        'r6_budget_event_update'=>['budget_review_events','UPDATE',"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Budget approval history is immutable'; END"],
        'r6_budget_event_delete'=>['budget_review_events','DELETE',"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Budget approval history is immutable'; END"],
        'r6_budget_draft_update'=>['budget_revision_drafts','UPDATE',"BEGIN IF OLD.state='Submitted' OR NEW.owner_id<>OLD.owner_id OR NEW.root_id<>OLD.root_id OR NEW.request_key<>OLD.request_key OR NEW.creation_hash<>OLD.creation_hash OR NOT(NEW.base_approved_id <=> OLD.base_approved_id) OR NEW.base_approval_epoch<>OLD.base_approval_epoch OR NOT(NEW.copied_revision_id <=> OLD.copied_revision_id) OR NEW.created_at<>OLD.created_at THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Budget draft identity and submitted content are immutable'; END IF; END"],
        'r6_budget_draft_delete'=>['budget_revision_drafts','DELETE',"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Budget draft history is retained'; END"],
        'r6_budget_root_delete'=>['budget_revision_roots','DELETE',"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Budget approval coordination is required'; END"],
    ];
}
function budget_revision_schema(PDO $pdo): array
{
    $tables=['budget_revision_roots','budget_revision_drafts','budget_revisions','budget_revision_allocations','budget_review_events'];$s=$pdo->query("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('budget_revision_roots','budget_revision_drafts','budget_revisions','budget_revision_allocations','budget_review_events')");$found=$s->fetchAll(PDO::FETCH_COLUMN);if(!$found)return ['state'=>'absent','complete'=>false];if(count($found)!==5)return ['state'=>'partial','complete'=>false];
    try{
        foreach(['budget_revision_roots'=>'id,budget_month,approved_revision_id,approval_epoch,next_revision','budget_revision_drafts'=>'id,root_id,owner_id,revision,request_key,creation_hash,payload,state,base_approved_id,base_approval_epoch,copied_revision_id,submitted_revision_id,created_at,updated_at','budget_revisions'=>'id,root_id,revision_number,draft_id,payload,payload_hash,draft_hash,expected_approved_id,expected_approval_epoch,prepared_by,prepared_at','budget_revision_allocations'=>'id,revision_id,account_id,project_id,bucket_key,amount,account_label,account_code,project_label,project_code','budget_review_events'=>'id,revision_id,decision,reason,actor_id,actor_name,request_key,request_hash,reviewed_at'] as $table=>$columns)$pdo->query('SELECT '.$columns.' FROM '.$table.' LIMIT 0');
        $triggers=[];foreach($pdo->query('SHOW TRIGGERS')->fetchAll(PDO::FETCH_ASSOC) as $t)$triggers[$t['Trigger']]=$t;$normal=static fn($v)=>strtolower(preg_replace('/[\s`]+/u','',$v));
        foreach(budget_trigger_contract() as $name=>[$table,$event,$body])if(!isset($triggers[$name])||$triggers[$name]['Table']!==$table||$triggers[$name]['Event']!==$event||$triggers[$name]['Timing']!=='BEFORE'||$normal($triggers[$name]['Statement'])!==$normal($body))return ['state'=>'partial','complete'=>false];
        foreach(['budget_revision_roots'=>[['budget_month']],'budget_revision_drafts'=>[['owner_id','request_key']],'budget_revisions'=>[['root_id','revision_number'],['draft_id']],'budget_revision_allocations'=>[['revision_id','account_id','bucket_key']],'budget_review_events'=>[['revision_id'],['actor_id','request_key']]] as $table=>$required){$indexes=[];foreach($pdo->query('SHOW INDEX FROM '.$table)->fetchAll(PDO::FETCH_ASSOC) as $i)if((int)$i['Non_unique']===0)$indexes[$i['Key_name']][(int)$i['Seq_in_index']]=$i['Column_name'];$unique=[];foreach($indexes as $columns){ksort($columns);$unique[]=array_values($columns);}foreach($required as $columns)if(!in_array($columns,$unique,true))return ['state'=>'partial','complete'=>false];}
        $s=$pdo->query("SELECT r.*,COALESCE((SELECT MAX(v.revision_number) FROM budget_revisions v WHERE v.root_id=r.id),0) max_revision,(SELECT COUNT(*) FROM budget_review_events e JOIN budget_revisions v ON v.id=e.revision_id WHERE v.root_id=r.id AND e.decision='Approved') approvals,(SELECT e.revision_id FROM budget_review_events e JOIN budget_revisions v ON v.id=e.revision_id WHERE v.root_id=r.id AND e.decision='Approved' ORDER BY e.id DESC LIMIT 1) last_approval FROM budget_revision_roots r");
        foreach($s as $r)if((int)$r['next_revision']!==(int)$r['max_revision']+1||(int)$r['approval_epoch']!==(int)$r['approvals']||$r['approved_revision_id']!==$r['last_approval']||substr($r['budget_month'],8,2)!=='01')return ['state'=>'partial','complete'=>false];
        $s=$pdo->query("SELECT CONSTRAINT_NAME,TABLE_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND CONSTRAINT_NAME LIKE 'r6_budget_%' AND REFERENCED_TABLE_SCHEMA=DATABASE()");$keys=[];foreach($s as $k)$keys[$k['CONSTRAINT_NAME']]=[$k['TABLE_NAME'],$k['COLUMN_NAME'],$k['REFERENCED_TABLE_NAME'],$k['REFERENCED_COLUMN_NAME']];
        $foldTables=(int)$pdo->query('SELECT @@lower_case_table_names')->fetchColumn()!==0;$normalizeKey=static function(array $shape)use($foldTables):array{if($foldTables){$shape[0]=strtolower($shape[0]);$shape[2]=strtolower($shape[2]);}return $shape;};
        foreach(['draft_root'=>['budget_revision_drafts','root_id','budget_revision_roots','id'],'owner'=>['budget_revision_drafts','owner_id','user_identities','UserID'],'revision_root'=>['budget_revisions','root_id','budget_revision_roots','id'],'source_draft'=>['budget_revisions','draft_id','budget_revision_drafts','id'],'preparer'=>['budget_revisions','prepared_by','user_identities','UserID'],'expected_approval'=>['budget_revisions','expected_approved_id','budget_revisions','id'],'approved'=>['budget_revision_roots','approved_revision_id','budget_revisions','id'],'base_approval'=>['budget_revision_drafts','base_approved_id','budget_revisions','id'],'copy'=>['budget_revision_drafts','copied_revision_id','budget_revisions','id'],'submitted'=>['budget_revision_drafts','submitted_revision_id','budget_revisions','id'],'allocation_revision'=>['budget_revision_allocations','revision_id','budget_revisions','id'],'allocation_account'=>['budget_revision_allocations','account_id','Categories','CategoryID'],'allocation_project'=>['budget_revision_allocations','project_id','projects','id'],'review_revision'=>['budget_review_events','revision_id','budget_revisions','id'],'reviewer'=>['budget_review_events','actor_id','user_identities','UserID']] as $key=>$shape)if(!isset($keys['r6_budget_'.$key])||$normalizeKey($keys['r6_budget_'.$key])!==$normalizeKey($shape))return ['state'=>'partial','complete'=>false];
        return ['state'=>'complete','complete'=>true];
    }catch(PDOException $e){return ['state'=>'partial','complete'=>false];}
}
function budget_revision_require(PDO $pdo): void
{
    report_configuration_require($pdo);if(!budget_revision_schema($pdo)['complete'])throw new ReportingProblem('Monthly budget preparation is unavailable until deployment is complete.',503);
}
function budget_revision_payload(array $r): array
{
    $month=reporting_month($r['month']??'');$note=reporting_text($r['note']??'',2000,'budget note');if(!is_array($r['lines']??null)||!array_is_list($r['lines'])||count($r['lines'])>2000)throw new ReportingProblem('Use at most 2,000 valid budget allocation cells.',400);$out=[];$seen=[];$total=0;
    foreach($r['lines'] as $line){if(!is_array($line))throw new ReportingProblem('Use a valid budget allocation.',400);$account=reporting_id($line['account_id']??null,'expense account');$project=reporting_id($line['project_id']??null,'project',true);$bucket=$project===null?'operations':'project:'.$project;$key=$account.':'.$bucket;if(isset($seen[$key]))throw new BudgetCellProblem('Use one allocation per expense account and project or operations.',$account,$project);$seen[$key]=true;
        $value=$line['amount']??null;if(is_string($value)&&preg_match('/\A[0-9]{1,3}(?:,[0-9]{3})+(?:\.[0-9]{1,2})?\z/',$value))$value=str_replace(',','',$value);try{$amount=reporting_amount($value,'budget allocation');}catch(ReportingProblem $e){throw new BudgetCellProblem($e->getMessage(),$account,$project,$e->status);}$cents=accounting_cents($amount);if($cents<0)throw new BudgetCellProblem('Budget allocations must be zero or positive.',$account,$project);try{$total=accounting_add($total,$cents);}catch(OverflowException $e){throw new ReportingProblem('The total budget exceeds the supported amount. Reduce the allocations before saving.',422);}$out[]=['account_id'=>$account,'project_id'=>$project,'bucket_key'=>$bucket,'amount'=>$amount];
    }
    usort($out,fn($a,$b)=>($a['account_id']<=>$b['account_id'])?:strcmp($a['bucket_key'],$b['bucket_key']));return ['month'=>$month,'note'=>$note,'lines'=>$out,'total'=>accounting_decimal($total)];
}
function budget_master_labels(PDO $pdo,array $payload): array
{
    $accounts=[];foreach(accounting_accounts($pdo) as $a)$accounts[(int)$a['CategoryID']]=$a;$projects=[];foreach($pdo->query('SELECT id,code,name,is_active FROM projects ORDER BY id') as $p)$projects[(int)$p['id']]=$p;$lines=[];
    foreach($payload['lines'] as $line){$a=$accounts[$line['account_id']]??null;$p=$line['project_id']===null?null:($projects[$line['project_id']]??null);if(!$a||$a['Account_Type']!=='Expense'||($line['project_id']!==null&&!$p))throw new ReportingProblem('Select existing expense accounts and projects. Organization operations is the separate untagged bucket.');$lines[]=$line+['account_label'=>$a['Name'],'account_code'=>$a['Account_Code'],'project_label'=>$p['name']??'Organization operations','project_code'=>$p['code']??null];}
    return $lines;
}
function budget_root(PDO $pdo,string $month,bool $lock=false): ?array
{
    $s=$pdo->prepare('SELECT * FROM budget_revision_roots WHERE budget_month=?'.($lock?' FOR UPDATE':''));$s->execute([reporting_month($month).'-01']);return $s->fetch(PDO::FETCH_ASSOC)?:null;
}
function budget_draft(PDO $pdo,int $uid,int $id,bool $lock=false): array
{
    reporting_actor($pdo,$uid,['Admin']);$s=$pdo->prepare('SELECT * FROM budget_revision_drafts WHERE id=? AND owner_id=?'.($lock?' FOR UPDATE':''));$s->execute([$id,$uid]);$d=$s->fetch(PDO::FETCH_ASSOC);if(!$d)throw new ReportingProblem('That private budget draft is unavailable.',404);$d['payload']=json_decode($d['payload'],true,64,JSON_THROW_ON_ERROR);$d['payload_hash']=hash('sha256',reporting_json($d['payload']));return $d;
}
/** Internal verified immutable projection. Entry points authenticate before calling. */
function budget_published(PDO $pdo,int $id): array
{
    $s=$pdo->prepare('SELECT v.*,r.budget_month,r.approved_revision_id,r.approval_epoch FROM budget_revisions v JOIN budget_revision_roots r ON r.id=v.root_id WHERE v.id=?');$s->execute([$id]);$v=$s->fetch(PDO::FETCH_ASSOC);if(!$v)throw new ReportingProblem('That submitted budget revision was not found.',404);$payload=json_decode($v['payload'],true,64,JSON_THROW_ON_ERROR);if(!hash_equals($v['payload_hash'],hash('sha256',reporting_json($payload))))throw new ReportingProblem('The submitted budget needs an integrity review.',503);
    try{$calculated=budget_revision_payload($payload);}catch(ReportingProblem $e){throw new ReportingProblem('The submitted budget contents need an integrity review.',503);}if($calculated['total']!==$payload['total'])throw new ReportingProblem('The submitted budget total needs an integrity review.',503);
    $s=$pdo->prepare('SELECT a.account_id,a.project_id,a.bucket_key,a.amount,a.account_label,a.account_code,a.project_label,a.project_code,c.Account_Type FROM budget_revision_allocations a JOIN Categories c ON c.CategoryID=a.account_id WHERE a.revision_id=? ORDER BY a.account_id,a.bucket_key');$s->execute([$id]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);$canonical=[];foreach($rows as $row){if($row['Account_Type']!=='Expense')throw new ReportingProblem('A submitted budget expense account needs an integrity review.',503);unset($row['Account_Type']);$row['account_id']=(int)$row['account_id'];$row['project_id']=$row['project_id']===null?null:(int)$row['project_id'];$row['amount']=accounting_decimal(accounting_cents($row['amount']));$canonical[]=$row;}if(reporting_json($canonical)!==reporting_json($payload['lines'])||$payload['month'].'-01'!==$v['budget_month'])throw new ReportingProblem('The submitted budget allocations need an integrity review.',503);
    $s=$pdo->prepare('SELECT id,decision,reason,actor_name,reviewed_at FROM budget_review_events WHERE revision_id=?');$s->execute([$id]);$event=$s->fetch(PDO::FETCH_ASSOC)?:null;
    if((int)($v['approved_revision_id']??0)===$id&&($event['decision']??null)!=='Approved')throw new ReportingProblem('The effective budget needs an approval integrity review.',503);
    return ['id'=>$id,'month'=>$payload['month'],'revision'=>(int)$v['revision_number'],'payload'=>$payload,'payload_hash'=>$v['payload_hash'],'prepared_by'=>$payload['prepared_name'],'prepared_at'=>$v['prepared_at'],'state'=>$event['decision']??'Submitted','review'=>$event,'is_effective'=>(int)($v['approved_revision_id']??0)===$id,'expected_approved_id'=>$v['expected_approved_id']===null?null:(int)$v['expected_approved_id'],'expected_approval_epoch'=>(int)$v['expected_approval_epoch'],'current_approved_id'=>$v['approved_revision_id']===null?null:(int)$v['approved_revision_id'],'current_approval_epoch'=>(int)$v['approval_epoch']];
}
function budget_save(PDO $pdo,int $uid,array $r,?callable $beforeCreate=null): array
{
    reporting_csrf($r);budget_revision_require($pdo);if(!is_array($r['payload']??null))throw new ReportingProblem('Use a valid budget draft.',400);$payload=budget_revision_payload($r['payload']);$id=reporting_id($r['draft_id']??null,'draft',true);$copy=reporting_id($r['copied_revision_id']??null,'source budget revision',true);$key=reporting_text($r['request_key']??'',64,'draft identity',true);if(!preg_match('/\A[a-f0-9]{64}\z/',$key))throw new ReportingProblem('Reload the budget draft and try again.',400);$hash=hash('sha256',reporting_json([$payload,$copy]));
    return reporting_tx($pdo,$uid,['Admin'],function()use($pdo,$uid,$r,$payload,$id,$copy,$key,$hash,$beforeCreate){
        budget_revision_require($pdo);
        if($id===null){$s=$pdo->prepare('SELECT id,creation_hash FROM budget_revision_drafts WHERE owner_id=? AND request_key=?');$s->execute([$uid,$key]);$old=$s->fetch(PDO::FETCH_ASSOC);if($old){if(!hash_equals($old['creation_hash'],$hash))throw new ReportingProblem('That draft identity was used with different contents.',409);return budget_draft($pdo,$uid,(int)$old['id']);}
            $pdo->prepare('INSERT INTO budget_revision_roots(budget_month) VALUES(?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)')->execute([$payload['month'].'-01']);$root=budget_root($pdo,$payload['month'],true);
            if($beforeCreate)$beforeCreate($root);
            if($copy){$source=budget_published($pdo,$copy);if($source['month']!==$payload['month'])throw new ReportingProblem('Copy a revision from this budget month.');}
            budget_master_labels($pdo,$payload);$s=$pdo->prepare('INSERT INTO budget_revision_drafts(root_id,owner_id,request_key,creation_hash,payload,base_approved_id,base_approval_epoch,copied_revision_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())');$s->execute([$root['id'],$uid,$key,$hash,reporting_json($payload),$root['approved_revision_id'],$root['approval_epoch'],$copy]);$id=(int)$pdo->lastInsertId();reporting_audit($pdo,$uid,AUDIT_ACTION_CREATE,'Budget draft',$id,null,['month'=>$payload['month'],'copied_revision_id'=>$copy]);
        }else{
            $peek=budget_draft($pdo,$uid,$id);$root=budget_root($pdo,$peek['payload']['month'],true);$d=budget_draft($pdo,$uid,$id,true);if($d['state']!=='Draft'||$d['request_key']!==$key||(string)$d['revision']!==(string)($r['revision']??''))throw new ReportingProblem('This budget draft changed. Reload it before saving; keep your entered amounts.',409);if((int)$d['root_id']!==(int)$root['id']||$payload['month']!==$d['payload']['month']||$copy!==($d['copied_revision_id']===null?null:(int)$d['copied_revision_id']))throw new ReportingProblem('The draft month and copied revision are fixed. Start a separate draft for another month.',409);budget_master_labels($pdo,$payload);
            $payloadHash=hash('sha256',reporting_json($payload));if(!hash_equals($d['payload_hash'],$payloadHash)){$pdo->prepare('UPDATE budget_revision_drafts SET payload=?,revision=revision+1,updated_at=UTC_TIMESTAMP() WHERE id=?')->execute([reporting_json($payload),$id]);reporting_audit($pdo,$uid,AUDIT_ACTION_EDIT,'Budget draft',$id,['payload_hash'=>$d['payload_hash']],['payload_hash'=>$payloadHash]);}
        }return budget_draft($pdo,$uid,$id);
    });
}
function budget_submit(PDO $pdo,int $uid,array $r): array
{
    reporting_csrf($r);budget_revision_require($pdo);$id=reporting_id($r['draft_id']??null,'draft');$hash=reporting_text($r['payload_hash']??'',64,'saved budget identity',true);if(!preg_match('/\A[a-f0-9]{64}\z/',$hash))throw new ReportingProblem('Save this budget draft before submitting.',400);
    $result=reporting_tx($pdo,$uid,['Admin'],function($actor)use($pdo,$uid,$r,$id,$hash){
        budget_revision_require($pdo);$peek=budget_draft($pdo,$uid,$id);if(!hash_equals($peek['payload_hash'],$hash))throw new ReportingProblem('Budget contents changed. Save and review this draft again.',409);
        if($peek['state']==='Submitted'){$s=$pdo->prepare('SELECT id,draft_hash FROM budget_revisions WHERE draft_id=?');$s->execute([$id]);$v=$s->fetch(PDO::FETCH_ASSOC);if(!$v||!hash_equals($v['draft_hash'],$hash)||(int)$peek['submitted_revision_id']!==(int)$v['id'])throw new ReportingProblem('The submitted budget needs an integrity review.',503);return ['id'=>(int)$v['id'],'duplicate'=>true];}
        $payload=budget_revision_payload($peek['payload']);$root=budget_root($pdo,$payload['month'],true);$d=budget_draft($pdo,$uid,$id,true);if($d['state']!=='Draft'||(string)$d['revision']!==(string)($r['revision']??'')||$root['approved_revision_id']!==$d['base_approved_id']||(int)$root['approval_epoch']!==(int)$d['base_approval_epoch'])throw new ReportingProblem('The effective budget changed while this draft was being prepared. Keep it and prepare a new revision from the latest approved budget.',409);
        $published=$payload;$published['lines']=budget_master_labels($pdo,$payload);$published['prepared_name']=$actor['FullName'];$published['copied_revision_id']=$d['copied_revision_id']===null?null:(int)$d['copied_revision_id'];$publishedHash=hash('sha256',reporting_json($published));
        $s=$pdo->prepare('INSERT INTO budget_revisions(root_id,revision_number,draft_id,payload,payload_hash,draft_hash,expected_approved_id,expected_approval_epoch,prepared_by,prepared_at) VALUES(?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP())');$s->execute([$root['id'],$root['next_revision'],$id,reporting_json($published),$publishedHash,$hash,$root['approved_revision_id'],$root['approval_epoch'],$uid]);$revision=(int)$pdo->lastInsertId();
        $s=$pdo->prepare('INSERT INTO budget_revision_allocations(revision_id,account_id,project_id,bucket_key,amount,account_label,account_code,project_label,project_code) VALUES(?,?,?,?,?,?,?,?,?)');foreach($published['lines'] as $line)$s->execute([$revision,$line['account_id'],$line['project_id'],$line['bucket_key'],$line['amount'],$line['account_label'],$line['account_code'],$line['project_label'],$line['project_code']]);
        $pdo->prepare("UPDATE budget_revision_drafts SET state='Submitted',submitted_revision_id=?,revision=revision+1,updated_at=UTC_TIMESTAMP() WHERE id=?")->execute([$revision,$id]);$pdo->prepare('UPDATE budget_revision_roots SET next_revision=next_revision+1 WHERE id=?')->execute([$root['id']]);reporting_audit($pdo,$uid,AUDIT_ACTION_CREATE,'Budget revision',$revision,null,['month'=>$payload['month'],'payload_hash'=>$publishedHash]);return ['id'=>$revision,'duplicate'=>false];
    });
    $result['warning']='';if(!$result['duplicate']&&!notification_notify_management($pdo,'Monthly budget submitted for review.','budgets.php?revision_id='.$result['id']))$result['warning']='Budget submitted, but its notification could not be delivered. It remains in the review queue.';return $result;
}
function budget_review(PDO $pdo,int $uid,array $r): array
{
    reporting_csrf($r);budget_revision_require($pdo);$id=reporting_id($r['revision_id']??null,'submitted budget');$decision=reporting_text($r['decision']??'',16,'budget decision',true);if(!in_array($decision,['Approved','Returned'],true))throw new ReportingProblem('Choose Approve or Return.',400);$reason=reporting_text($r['reason']??'',2000,'review reason',$decision==='Returned');$key=reporting_text($r['request_key']??'',64,'review identity',true);$content=reporting_text($r['payload_hash']??'',64,'submitted budget identity',true);$epoch=$r['expected_approval_epoch']??null;$approved=reporting_id($r['expected_approved_id']??null,'approved budget',true);
