    $result=reporting_tx($pdo,$uid,['Management'],function($actor)use($pdo,$uid,$id,$decision,$reason,$key,$content,$epoch,$approved,$requestHash){
        budget_revision_require($pdo);$s=$pdo->prepare('SELECT * FROM budget_review_events WHERE actor_id=? AND request_key=?');$s->execute([$uid,$key]);$old=$s->fetch(PDO::FETCH_ASSOC);if($old){if(!hash_equals($old['request_hash'],$requestHash)||(int)$old['revision_id']!==$id)throw new ReportingProblem('That review identity was used for a different decision.',409);return ['id'=>$id,'event_id'=>(int)$old['id'],'duplicate'=>true];}
        $peek=budget_published($pdo,$id);if(!hash_equals($peek['payload_hash'],$content))throw new ReportingProblem('Review the exact submitted budget before deciding.',409);if($peek['state']!=='Submitted')throw new ReportingProblem('This budget already has a recorded decision. Open its recorded result.',409);
        // Only approval changes effective monthly report basis. Recover committed retries first.
        if($decision==='Approved')reporting_basis_guard($pdo,$peek['month'].'-01',reporting_month_range($peek['month'])[1]);
        $root=budget_root($pdo,$peek['month'],true);$v=budget_published($pdo,$id);
        if($decision==='Approved'&&((int)$root['approval_epoch']!==$epoch||$v['expected_approval_epoch']!==$epoch||($root['approved_revision_id']===null?null:(int)$root['approved_revision_id'])!==$approved||$v['expected_approved_id']!==$approved))throw new ReportingProblem('A different budget has become effective. Return this older submission and prepare a new revision from the latest approved budget.',409);
        $s=$pdo->prepare('INSERT INTO budget_review_events(revision_id,decision,reason,actor_id,actor_name,request_key,request_hash,reviewed_at) VALUES(?,?,?,?,?,?,?,UTC_TIMESTAMP())');$s->execute([$id,$decision,$reason,$uid,$actor['FullName'],$key,$requestHash]);$event=(int)$pdo->lastInsertId();if($decision==='Approved'){$pdo->prepare('UPDATE budget_revision_roots SET approved_revision_id=?,approval_epoch=approval_epoch+1 WHERE id=?')->execute([$id,$root['id']]);stage1_write_changed($pdo);}
        reporting_audit($pdo,$uid,AUDIT_ACTION_EDIT,'Budget review',$event,null,['budget_revision_id'=>$id,'decision'=>$decision,'reason'=>$reason,'payload_hash'=>$content]);return ['id'=>$id,'event_id'=>$event,'duplicate'=>false];
    });$result['warning']='';if(!$result['duplicate']){$s=$pdo->prepare('SELECT prepared_by FROM budget_revisions WHERE id=?');$s->execute([$id]);if(!notification_create($pdo,(int)$s->fetchColumn(),null,'Your monthly budget was '.strtolower($decision).'.','budgets.php?revision_id='.$id))$result['warning']='Budget decision saved, but its notification could not be delivered.';}return $result;
}
function budget_workspace(PDO $pdo,int $uid,string $month,?int $draft=null,?int $revision=null): array
{
    return accounting_read($pdo,function()use($pdo,$uid,$month,$draft,$revision){$actor=reporting_actor($pdo,$uid);budget_revision_require($pdo);$month=reporting_month($month);$selected=$revision?budget_published($pdo,$revision):null;if($selected)$month=$selected['month'];$owned=$draft?budget_draft($pdo,$uid,$draft):null;if($owned)$month=$owned['payload']['month'];$root=budget_root($pdo,$month);$effective=$root&&$root['approved_revision_id']?budget_published($pdo,(int)$root['approved_revision_id']):null;
        $s=$pdo->prepare('SELECT v.id,v.revision_number,v.prepared_at,COALESCE(e.decision,\'Submitted\') state FROM budget_revisions v JOIN budget_revision_roots r ON r.id=v.root_id LEFT JOIN budget_review_events e ON e.revision_id=v.id WHERE r.budget_month=? ORDER BY v.revision_number DESC');$s->execute([$month.'-01']);$revisions=$s->fetchAll(PDO::FETCH_ASSOC);$drafts=[];if($actor['Role']==='Admin'){$s=$pdo->prepare("SELECT id,revision,updated_at FROM budget_revision_drafts WHERE owner_id=? AND root_id=? AND state='Draft' ORDER BY id DESC");$s->execute([$uid,$root['id']??0]);$drafts=$s->fetchAll(PDO::FETCH_ASSOC);}
        return ['month'=>$month,'role'=>$actor['Role'],'draft'=>$owned,'selected'=>$selected,'effective'=>$effective,'revisions'=>$revisions,'drafts'=>$drafts,'accounts'=>array_values(array_filter(accounting_accounts($pdo),fn($a)=>$a['Account_Type']==='Expense')),'projects'=>$pdo->query('SELECT id,code,name,is_active FROM projects ORDER BY name,id')->fetchAll(PDO::FETCH_ASSOC)];
    });
}
function budget_pending(PDO $pdo,int $uid,int $limit=100): array
{
    reporting_actor($pdo,$uid);$schema=budget_revision_schema($pdo);if($schema['state']==='absent')return [];if(!$schema['complete'])throw new ReportingProblem('Budget review records need a deployment integrity review.',503);if($limit<1||$limit>100)throw new LogicException('Invalid queue bound.');return $pdo->query("SELECT v.id,v.revision_number,r.budget_month,v.prepared_at FROM budget_revisions v JOIN budget_revision_roots r ON r.id=v.root_id LEFT JOIN budget_review_events e ON e.revision_id=v.id WHERE e.id IS NULL ORDER BY r.budget_month,v.id LIMIT ".$limit)->fetchAll(PDO::FETCH_ASSOC);
}
function budget_review_queue(PDO $pdo,int $uid,string $filter='pending',int $limit=100): array
{
    return accounting_read($pdo,function()use($pdo,$uid,$filter,$limit){reporting_actor($pdo,$uid);$schema=budget_revision_schema($pdo);if($schema['state']==='absent')return [];if(!$schema['complete'])throw new ReportingProblem('Budget review records need a deployment integrity review.',503);if(!in_array($filter,['pending','all'],true)||$limit<1||$limit>100)throw new LogicException('Invalid budget queue scope.');return $pdo->query("SELECT v.id,v.revision_number,r.budget_month,v.prepared_at,COALESCE(e.decision,'Submitted') state FROM budget_revisions v JOIN budget_revision_roots r ON r.id=v.root_id LEFT JOIN budget_review_events e ON e.revision_id=v.id ".($filter==='pending'?'WHERE e.id IS NULL ':'').'ORDER BY r.budget_month DESC,v.id DESC LIMIT '.$limit)->fetchAll(PDO::FETCH_ASSOC);});
}
